import{_ as i,l as n,o as e,c as s,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"影子分页对照","description":"","frontmatter":{"title":"影子分页对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shadow-paging.md","filePath":"cs/shadow-paging.md","lastUpdated":1789023840000}'),h={name:"cs/shadow-paging.md"};function A(_,a,E,u,m,L){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="影子分页对照" tabindex="-1">影子分页对照 <a class="header-anchor" href="#影子分页对照" aria-label="Permalink to &quot;影子分页对照&quot;">​</a></h1><div class="epigraph"><p>影子分页写新页并切换根：提交即新树可见，无需 redo 前滚。随机写与大目录更新是代价，现代 OLTP 主路径仍是 WAL 原地。</p><footer>—— 据 Lorie 影子分页；Gray and Reuter 对照；SQLite 回滚模式点名</footer></div><p><a href="/cs/logging-granularity">上一课</a>选了记什么。本课对照<strong>不原地更新</strong>的恢复：影子分页（shadow paging）。主干 WAL 是主路径；进阶用对照理解为何 ARIES 赢在随机 I/O 与细粒度。组提交下一课把 WAL 刷盘摊掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每页有当前与影子。事务写时拷页到新位置（COW），修改页表（或文件 inode 树）。提交：原子切换根指针（一次 I/O）。崩溃：根仍指旧树，新页丢弃。缺口是<strong>页表本身很大</strong>：更新一条索引可能级联大量目录页，写放大；难以 steal 单页而不暴露。并发：两事务 COW 同一页要合并。</p><p>SQLite 历史上 rollback journal / WAL 模式切换，是影子与日志在嵌入式上的产品对照。LMDB 一类 COW B+ 也是影子亲戚。</p><p><span class="marginnote">Raymond Lorie 影子分页。Gray and Reuter 分析为何大型系统偏 WAL。本课不是教「用影子替换 InnoDB」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：跟随当前根。写：分配新页号，拷旧，改，更新父（可能再 COW）。提交：fsync 新页与新根。检查点：可丢弃不可达旧页当 GC——与 MVCC 版本回收神似，粒度为页。</p><p>与 WAL 混合：写前日志仍可有，影子管页原子。现代常用 WAL+原地+doublewrite，少用纯影子。</p>',10)),(e(),l(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B9%E6%A0%91%22%5D%20--%3E%20COW%5B%22%E5%86%99%E6%97%B6%E6%8B%B7%E9%A1%B5%22%5D%0A%20%20COW%20--%3E%20NEW%5B%22%E6%96%B0%E6%A0%B9%22%5D%0A%20%20NEW%20--%3E%20COM%5B%22%E5%8E%9F%E5%AD%90%E5%88%87%E6%8D%A2%E6%A0%B9%22%5D%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20OLD%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优点：恢复快（几乎不用 redo 长扫描），实现直观。缺点：随机分配页破坏聚簇、碎片、并发粒度粗、目录更新重。LSM 不可变文件+元数据指针切换，是文件级影子，吸收了「切换根」思想而把随机写变成顺序文件。</p><p>ARIES 用顺序日志换随机数据页延迟写，与影子的随机新页对偶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲组提交。也不把 ZFS CoW 当数据库事务。RTO 下一课之后量化。</p><p>后课默认：大型并发库用 WAL+ARIES；影子/COW 出现在嵌入式或文件级元数据。组提交：多事务共享一次 fsync。</p><p>影子的原子单位是根切换；WAL 的原子单位是日志尾。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子 COW+切根，恢复简单，随机写与目录放大差。</li><li>LSM/文件元数据吸收了切根思想。</li><li>组提交下一课：摊掉 WAL 的 fsync。</li><li>出处：Lorie；Gray and Reuter；SQLite/LMDB 对照。</li></ul>',9))])}const B=i(h,[["render",A]]);export{g as __pageData,B as default};
